for (int i = 0; i < 5_000; i++) {
    words.add("w" + i);
}
checkEq(upperCased(words, false), upperCased(words, true));
checkEq(upperCased(List.of("a", "b"), true), List.of("A", "B"));
checkEq(upperCased(words, true).size(), 5_000);
checkEq(upperCased(words, true).get(0), "W0");

