checkEq(countByFirstLetter(mixed, false), countByFirstLetter(mixed, true));
checkEq(countByFirstLetter(mixed, true), Map.of("a", 2_000L, "b", 2_000L, "c", 2_000L));
checkEq(countByFirstLetter(List.of(), true), Map.of());

